import numpy as np, generate
from PIL import Image
center=np.array([112.25,47.15]); u=np.array([20.,5.]); v=np.array([-4.,7.])
# brute optimize polygon IoU against mask
im=np.asarray(Image.open('first_frame.png'))
y,x=np.indices((144,256)); target=(im[:,:,2].astype(int)-im[:,:,0].astype(int)>20)&(im[:,:,0]>110)&(y>=41)&(y<=53)&(x>=98)&(x<=128)
best=[]
for cx in np.arange(111.0,113.51,.25):
 for cy in np.arange(46.5,48.01,.25):
  for ux in np.arange(19,22.1,.5):
   for uy in np.arange(4,6.1,.5):
    for vx in np.arange(-5,-2.9,.5):
     for vy in np.arange(6,8.1,.5):
      c=np.array([cx,cy]); uu=np.array([ux,uy]); vv=np.array([vx,vy])
